function makeMembrane(target) {
  const raw2wrap = new WeakMap();                // identity map, per membrane
  const handler = { get: (t, k) => { const m = Reflect.get(t, k, t);   // forward...
    return typeof m === 'function' ? (...a) => wrap(m.apply(t, a.map(wrap))) : wrap(m);
  } };                                           // ...and wrap both directions
  const wrap = (v) => { if (v === null || typeof v !== 'object') return v;  // caps only
    if (!raw2wrap.has(v)) raw2wrap.set(v, new Proxy(v, handler));
    return raw2wrap.get(v);                      // one wrapper per raw object
  };
  const { proxy, revoke } = Proxy.revocable(target, handler);   // kill switch
  return { view: proxy, wrap, revoke };
}
